def sha(data):
    return hashlib.sha256(data).hexdigest()


def unpack():
    raw = zlib.decompress(base64.b85decode(PAYLOAD))
    if sha(raw) != BUNDLE_SHA256:
        raise RuntimeError('Archive intégrée altérée')
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        files = {}
        for item in archive.infolist():
            path = Path(item.filename)
            if item.is_dir():
                continue
            if path.is_absolute() or '..' in path.parts or '\\' in item.filename:
                raise RuntimeError('Chemin invalide dans le paquet')
            files[item.filename] = archive.read(item)
    return files


def check_targets(root, files, old_hashes=OLD_HASHES):
    changes = []
    for name, data in files.items():
        target = root/name
        if not target.resolve().is_relative_to(root) or any(p.is_symlink() for p in [target,*target.parents] if p != root.parent):
            raise RuntimeError('Lien symbolique ou chemin extérieur refusé : '+name)
        if target.exists():
            if not target.is_file():
                raise RuntimeError('Chemin occupé : '+name)
            actual = sha(target.read_bytes())
            if actual == sha(data):
                continue
            if actual != old_hashes.get(name):
                raise RuntimeError('Fichier modifié hors du paquet, conservé : '+name)
        elif name in old_hashes:
            raise RuntimeError('Fichier source attendu absent : '+name)
        changes.append(name)
    return changes


def processes(root):
    result = []
    for p in Path('/proc').iterdir():
        if not p.name.isdigit() or int(p.name) == os.getpid():
            continue
        try:
            if (p/'cwd').resolve() != root:
                continue
            args = [x.decode() for x in (p/'cmdline').read_bytes().split(b'\0') if x]
            executable = (p/'exe').resolve().name
            script_index = next((i for i,x in enumerate(args[1:],1) if not x.startswith('-')),None)
            script = (root/args[script_index]).resolve() if script_index is not None else None
            python_flags = args[1:script_index] if script_index is not None else []
            if (executable.startswith('python') and script == root/'app.py'
                    and all(x in ('-u','-B','-E','-s') for x in python_flags)):
                if p.stat().st_uid != os.getuid():
                    raise RuntimeError('Scanner appartenant à un autre utilisateur')
                starttime = (p/'stat').read_text().rsplit(')',1)[1].split()[19]
                result.append((int(p.name),args,starttime))
        except (OSError,UnicodeError):
            continue
    return result


def observe_arguments(args):
    index = next(i for i,a in enumerate(args) if Path(a).name == 'app.py')
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('--mode',default='observe')
    parser.add_argument('--host',default='127.0.0.1')
    parser.add_argument('--port',type=int,default=8083)
    parser.add_argument('--data-dir',default='data_v3')
    parser.add_argument('--policy')
    parsed, unknown = parser.parse_known_args(args[index+1:])
    if unknown or parsed.mode != 'observe':
        raise RuntimeError('Seul un scanner explicitement en observation peut être relancé par cet installateur')
    return parsed


def read_status(port):
    with urlopen(f'http://127.0.0.1:{port}/api/status',timeout=5) as response:
        return json.load(response)


def confirm_observe(port):
    s = read_status(port)
    if s.get('mode') != 'observe' or s.get('live') is not None:
        raise RuntimeError('Le statut ne confirme pas une observation sans adaptateur LIVE')
    return s


def terminate_observe(pid, args, root, starttime):
    options = observe_arguments(args)
    confirm_observe(options.port)
    if not hasattr(os,'pidfd_open') or not hasattr(signal,'pidfd_send_signal'):
        raise RuntimeError('Relance refusée : suivi de PID indisponible')
    fd = os.pidfd_open(pid)
    try:
        if (pid,args,starttime) not in processes(root):
            raise RuntimeError('Le processus a changé pendant la vérification')
        confirm_observe(options.port)
        signal.pidfd_send_signal(fd,signal.SIGTERM)
        if not select.select([fd],[],[],30)[0]:
            raise RuntimeError('Arrêt encore en cours ; aucune source installée et aucun nouveau processus lancé')
    finally:
        os.close(fd)
    return options


def verify(files):
    with tempfile.TemporaryDirectory(prefix='mexc_v3_verified_') as tmp:
        root = Path(tmp)
        for name,data in files.items():
            p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
        run=subprocess.run([sys.executable,str(root/'verifier_v3.py')],cwd=root,
                           text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=180)
        if run.returncode:
            print(run.stdout[-12000:])
            raise RuntimeError('Validation échouée : scanner et sources conservés')
        print(run.stdout.splitlines()[-1])
        return run.stdout


def install(root, files, changes, validation):
    now=datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S_%f')
    backup_dir=root/'backups_v3';backup_dir.mkdir(exist_ok=True)
    backup=backup_dir/('code_avant_correctif_'+now+'.zip')
    with zipfile.ZipFile(backup,'x',compression=zipfile.ZIP_DEFLATED) as z:
        for name in changes:
            p=root/name
            if p.exists():z.writestr(name,p.read_bytes())
        z.writestr('INSTALLATION.json',json.dumps({'release':RELEASE,'changed':changes,'new_files':[n for n in changes if not (root/n).exists()]},indent=2))
        z.writestr('validation.txt',validation)
    # All paths/hashes were validated together before this mutation. Each
    # replace is atomic; manifest is replaced last. Interrupted installs fail
    # integrity verification, and re-running accepts old or exact new bytes.
    for name in sorted(changes,key=lambda n:n=='SHA256SUMS.txt'):
        p=root/name;p.parent.mkdir(parents=True,exist_ok=True)
        fd,tmp=tempfile.mkstemp(prefix='v3_replace_',dir=p.parent)
        try:
            with os.fdopen(fd,'wb') as f:
                f.write(files[name]);f.flush();os.fsync(f.fileno())
            os.chmod(tmp,0o644)
            os.replace(tmp,p)
        finally:
            if os.path.exists(tmp):os.unlink(tmp)
    print('Sauvegarde du code :',backup)


def restart(root, options):
    env=dict(os.environ)
    for name in ('MEXC_API_KEY','MEXC_API_SECRET','MEXC_SECRET_KEY'):
        env.pop(name,None)
    env['MEXC_V3_LIVE']='0'
    args=[sys.executable,'app.py','--mode','observe','--host',options.host,
          '--port',str(options.port),'--data-dir',options.data_dir]
    if options.policy:args+=['--policy',options.policy]
    with open(root/'scanner_v3_observe.log','ab',buffering=0) as log:
        child=subprocess.Popen(args,cwd=root,env=env,stdout=log,stderr=subprocess.STDOUT,
                               stdin=subprocess.DEVNULL,start_new_session=True)
    print('Nouveau PID observation :',child.pid,flush=True)
    deadline=time.monotonic()+90
    while time.monotonic()<deadline:
        if child.poll() is not None:
            raise RuntimeError('Le nouveau scanner a quitté : consulter scanner_v3_observe.log ; LIVE non armé')
        try:
            state=confirm_observe(options.port)
            if state.get('version') == RELEASE:
                print('Version :',state['version'],'| mode : observation')
                print('Les carnets se reconstruisent. Aucun réarmement LIVE.')
                print('Qualification :',sys.executable,'qualifier_v3.py --url',f'http://127.0.0.1:{options.port}','--minutes 15')
                return
        except Exception:
            pass
        time.sleep(1)
    raise RuntimeError('Démarrage non confirmé ; le processus reste en observation. Consulter le journal avant toute autre relance.')


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--root',type=Path,default=Path(__file__).resolve().parent)
    p.add_argument('--apply',action='store_true')
    p.add_argument('--restart-observation',action='store_true')
    a=p.parse_args();root=a.root.resolve()
    if not (root/'app.py').is_file() or not (root/'mexc_v3').is_dir():
        raise RuntimeError('Placer cet installateur à la racine du dépôt V3 structuré')
    files=unpack();changes=check_targets(root,files)
    print('Correctif :',RELEASE,';',len(changes),'fichiers à installer')
    if not a.apply:
        print('Aperçu uniquement. Utiliser --apply --restart-observation pour installer et relancer le scanner en observation.')
        return
    with open(root/'.v3_update.lock','a+') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        validation=verify(files)
        running=processes(root)
        if len(running)>1:
            raise RuntimeError('Plusieurs scanners détectés ; aucune modification')
        if running and not a.restart_observation:
            raise RuntimeError('Scanner actif : utiliser --restart-observation pour un arrêt suivi et une relance sans LIVE')
        changes=check_targets(root,files)
        options=None
        if running:
            pid,args,starttime=running[0]
            options=terminate_observe(pid,args,root,starttime)
        changes=check_targets(root,files)
        if changes:install(root,files,changes,validation)
        print('Sources validées. Journaux, soldes simulés, historique et quotas conservés.')
        if options:
            restart(root,options)
        elif a.restart_observation:
            options=argparse.Namespace(host='0.0.0.0',port=8081,data_dir='data_v3',policy=None)
            restart(root,options)


if __name__=='__main__':
    try:main()
    except Exception as exc:
        print('Installation interrompue :',str(exc),file=sys.stderr)
        raise SystemExit(1)
